/* Own seven-part composition. Contemporary exercises, never a historical claim. */
import {createId} from './store.js';
import {artifactEvidence} from './quests.js';
export const principles=[['Mentalismus','Záměr','Který konkrétní detail se objevil, když jsi změnil svou otázku?','mentalism'],['Korespondence','Vazba','Zapiš podobnost detailu a celku; připiš, kde přirovnání končí.','correspondence'],['Vibrace','Puls','Popiš vlastní změnu tempa a to, jak změnila dojem.','vibration'],['Polarita','Kontrast','Napiš dvě rozdílná čtení jedné vlastní práce.','polarity'],['Rytmus','Návrat','Kde má tvůj text, obraz nebo rytmus pauzu a návrat?','rhythm'],['Příčina a následek','Rozhodnutí','Pojmenuj jednu změnu a konkrétní následek ve svém díle.','cause-effect'],['Gender','Souhra funkcí','Jak v tvé práci spolupracuje přijímání podnětů a tvoření? Nejde o vlastnosti pohlaví.','generation']];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function compositionSvg(entries,alias='SELFMADE'){
 const values=principles.map((p,i)=>({label:p[1],text:String(entries?.[i]||'').slice(0,500)}));
 const geometry=values.map((p,i)=>{const a=(-90+i*360/7)*Math.PI/180,x=450+Math.cos(a)*250,y=350+Math.sin(a)*250,xx=450+Math.cos(a)*140,yy=350+Math.sin(a)*140;return `<g><path d="M450 350L${x.toFixed(1)} ${y.toFixed(1)}" stroke="${p.text?'#FFD600':'#38362a'}"/><circle cx="${xx.toFixed(1)}" cy="${yy.toFixed(1)}" r="${p.text?14:5}" fill="${p.text?'#FFD600':'#38362a'}"/><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="35" fill="#080808" stroke="${p.text?'#FFD600':'#38362a'}" stroke-width="2"/><text x="${x.toFixed(1)}" y="${(y+5).toFixed(1)}" text-anchor="middle" font-size="16" fill="#F5F1E8">${i+1}</text><title>${esc(p.label+': '+p.text)}</title></g>`;}).join('');
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 760" role="img" aria-label="Vlastní sedmidílná kompozice ${esc(alias)}"><rect width="900" height="760" fill="#080808"/><g fill="none" stroke="#68602c"><circle cx="450" cy="350" r="250"/><circle cx="450" cy="350" r="205" stroke-dasharray="3 12"/><path d="M450 60L700 495H200ZM450 640L200 205H700Z"/></g>${geometry}<circle cx="450" cy="350" r="82" fill="#080808" stroke="#FFD600" stroke-width="3"/><path d="M395 350Q450 290 505 350Q450 410 395 350Z" fill="none" stroke="#FFD600" stroke-width="3"/><circle cx="450" cy="350" r="18" fill="#FFD600"/><text x="450" y="695" text-anchor="middle" font-family="sans-serif" font-weight="800" font-size="32" fill="#FFD600">${esc(String(alias).slice(0,32))}</text><text x="450" y="730" text-anchor="middle" font-family="sans-serif" font-size="12" fill="#F5F1E8">VLASTNÍ CVIČENÍ / SOUČASNÁ FILOZOFICKÁ INTERPRETACE</text></svg>`;
}
export function mountPractice(root,{store,notify=()=>{}}){
 let urls=[],pending=false,notes=principles.map((_,i)=>typeof store.get().drafts.principles?.notes?.[i]==='string'?store.get().drafts.principles.notes[i].slice(0,500):''),destroyed=false;
 root.innerHTML=`<div class="practice-head"><p class="eyebrow">SEDM OTÁZEK / JEDNA VLASTNÍ KOMPOZICE</p><h3>AS ABOVE.<br><em>YOUR OWN BELOW.</em></h3><p>Kybalion (1908) je moderní hermeticky inspirovaný text. Následující otázky jsou autorská tvůrčí zadání, ne důkaz metafyzických zákonů.</p><a href="/#principles">Filozofický kontext a zdroje ↗</a></div><div class="practice-grid"><div>${principles.map((p,i)=>`<details${i===0?' open':''}><summary>0${i+1} / ${p[0]} — ${p[1]}</summary><p>${esc(p[2])}</p><label>Moje vlastní cvičení<textarea data-practice="${i}" maxlength="500" rows="3">${esc(notes[i]||'')}</textarea></label><a href="/q/${p[3]}/">Otevřít celý princip ↗</a></details>`).join('')}</div><div><div data-practice-preview>${compositionSvg(notes,store.get().profile.alias)}</div><p class="smallprint">Rozsvícené uzly označují tvoje skutečně vyplněné odpovědi. Nejde o skóre znalostí. Význam jednotlivých částí zůstává v textu.</p><button type="button" class="play-button" data-practice-save>ULOŽIT SEDMIDÍLNOU KOMPOZICI ↗</button><button type="button" data-practice-export>EXPORT VLASTNÍHO SVG ↓</button><p data-practice-status role="status"></p></div></div><div class="practice-tools"><p class="eyebrow">NÁSTROJ NAVAZUJE NA TVOJI PRÁCI</p><h4>První pokus otevře další otázku.</h4><p>Šablony pomáhají porovnat konkrétní rozhodnutí. Odborné zvládnutí neodemyká počet kliknutí.</p><div data-practice-tools></div></div>`;
 function flush(){if(!pending)return;pending=false;const ok=store.update(s=>{s.drafts.principles={...(s.drafts.principles||{}),notes:[...notes]};});if(!ok)notify('Odpovědi zůstávají v paměti. Exportuj zálohu v Blackbooku.');}
 function renderTools(){const hasAttempt=store.get().artifacts.some(a=>artifactEvidence(a).hasAttempt);root.querySelector('[data-practice-tools]').innerHTML=hasAttempt?`<button data-template="revise" type="button">Šablona: první → úprava → přenos</button><button data-template="constraint" type="button">Šablona: dvě barvy / čtyři bary</button><p class="smallprint">Navazuje na tvoji uloženou práci. Šablonu upravíš v inventáři.</p>`:'<p class="smallprint">Nejprve ulož vlastní pokus v dílně. Potom tu najdeš šablony pro jeho revizi.</p>';}
 function input(e){if(e.target.matches('[data-practice]')){notes[Number(e.target.dataset.practice)]=e.target.value;pending=true;root.querySelector('[data-practice-preview]').innerHTML=compositionSvg(notes,store.get().profile.alias);}}
 function change(e){if(e.target.matches('[data-practice]'))flush();}
 function click(e){const button=e.target.closest('button');if(!button)return;if(button.hasAttribute('data-practice-save')){flush();if(notes.filter(v=>v?.trim()).length!==7){notify('Doplň vlastní zkušenost ke všem sedmi částem. Rozpracované odpovědi už máš zachované.');return;}const now=new Date().toISOString(),version={id:createId('version'),createdAt:now,text:principles.map((p,i)=>`${i+1} / ${p[0]}\n${notes[i]}`).join('\n\n'),decision:'Sestavil jsem vlastní sedmidílnou kompozici z konkrétních cvičení.',nextStep:'Ověřit jednu otázku na další vlastní práci.',composition:{kind:'seven',entries:[...notes]}};const ok=store.update(s=>{let a=s.artifacts.find(a=>a.id===s.drafts.principles?.artifactId);if(!a){a={id:createId('principle'),discipline:'knowledge',title:'Můj sedmidílný svět',createdAt:now,updatedAt:now,versions:[]};s.artifacts.push(a);}a.versions.push(version);a.updatedAt=now;s.drafts.principles={notes:[...notes],artifactId:a.id};});if(ok)notify('Sedm vlastních cvičení je v Blackbooku. SVG si můžeš samostatně stáhnout.');}if(button.hasAttribute('data-practice-export')){const url=URL.createObjectURL(new Blob([compositionSvg(notes,store.get().profile.alias)],{type:'image/svg+xml'}));urls.push(url);const a=document.createElement('a');a.href=url;a.download='caisik-vlastni-sedmidilna-kompozice.svg';a.click();root.querySelector('[data-practice-status]').textContent='SVG soubor byl připraven ke stažení.';}if(button.dataset.template){const text=button.dataset.template==='revise'?'První pokus:\nCo konkrétně měním:\nDůvod změny:\nCo vidím/slyším po úpravě:\nKam princip přenesu:':'Vlastní materiál:\nOmezení (dvě barvy / čtyři bary):\nPrvní pokus:\nCo omezení ukázalo:\nDalší varianta:';if(store.update(s=>{s.inventory.push({id:createId('template'),type:'note',title:'Pracovní šablona / vlastní revize',text,source:'Původní pracovní pomůcka CAISIK',createdAt:new Date().toISOString()});}))notify('Pracovní šablona je ve tvém inventáři.');}}
 root.addEventListener('input',input);root.addEventListener('change',change);root.addEventListener('click',click);const onPage=()=>flush();window.addEventListener('pagehide',onPage);const sub=store.subscribe(()=>{if(!destroyed)renderTools();});renderTools();return()=>{flush();destroyed=true;sub();root.removeEventListener('input',input);root.removeEventListener('change',change);root.removeEventListener('click',click);window.removeEventListener('pagehide',onPage);urls.forEach(u=>URL.revokeObjectURL(u));};
}
